import math
def priority(task, state, k0=0.5, k_cong=1.0, k_queue=0.02, wait_scale=1.0, late_boost=1.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    cap = max(state.capacity, 1e-6)
    congestion = state.queue_work / cap
    k = k0 / max(1.0 + k_cong * congestion + k_queue * state.queue_len, 1e-6)
    k = max(k, 1e-6)
    wait_est = wait_scale * r * congestion / cap
    slack = task.due - state.now - p - wait_est
    denom = max(k * max(state.mean_est, 1e-6), 1e-6)
    if slack <= 0.0:
        return task.weight / p * (1.0 + late_boost * (-slack) / denom)
    else:
        return task.weight / p * math.exp(-slack / denom)  # tuned (k0=0.41,k_cong=0.273,k_queue=0.0186,wait_scale=0.718,late_boost=2.44)

import math
def priority(task, state, k=1.0, alpha=0.3, load_coef=0.5, free_coef=0.5, premium=1.5, aging=0.1, type_align=1.0, type_variant=1.2, type_sv=0.9):
    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    denom = 1.0 + max(0.0, slack) / max(k * mean_est, 1e-6)
    urg = 1.0 / denom
    if slack < 0:
        urg *= (1.0 + (-slack) / mean_est)
    load = state.queue_work / max(state.capacity * mean_est, 1e-6)
    urg *= (1.0 + load_coef * load)
    free = max(state.free, 0.0)
    if need <= free:
        urg *= (1.0 + free_coef * need / max(free, 1e-6))
    else:
        urg *= (1.0 / max(1.0 + free_coef * (need - free) / max(state.capacity, 1e-6), 1e-6))
    base = task.weight * urg / (est * (need ** alpha))
    if task.tenant == 'premium':
        base *= premium
    base *= (1.0 + aging * max(0.0, state.now - task.release) / mean_est)
    if task.task_type == 'variant_calling':
        base *= type_variant
    elif task.task_type == 'sv_calling':
        base *= type_sv
    else:
        base *= type_align
    return base  # tuned (k=0.411,alpha=0.0808,load_coef=0.246,free_coef=1.28,premium=0.695,aging=0.243,type_align=2.31,type_variant=1.3,type_sv=3.24)

