def priority(task, state, k=0.5, alpha=0.8, beta=0.1, m_align=1.0, m_var=1.0, m_sv=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    wait = max(0.0, state.now - task.release)
    aging = 1.0 + beta * wait / max(est, mean_est, 1e-6)
    core_pressure = max(0.0, min(1.0, 1.0 - state.free / max(state.capacity, 1e-6)))
    core_factor = 1.0 / max(task.resource_need, 1e-6) ** (alpha * core_pressure)
    if task.task_type == 'alignment':
        mult = m_align
    elif task.task_type == 'variant_calling':
        mult = m_var
    else:
        mult = m_sv
    return mult * task.weight / est * math.exp(-slack / max(k * mean_est, 1e-6)) * aging * core_factor  # tuned (k=0.203,alpha=0.323,beta=0.0549,m_align=2.28,m_var=2.54,m_sv=2.24)

def priority(task, state, c=1.0, a=0.0, r=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    cores = max(task.resource_need, 1e-6)
    slack = task.due - state.now - est
    if state.queue_work > c * state.capacity * mean_est and slack < a * mean_est:
        return task.weight / (est * (cores ** r))
    return -task.due

