def priority(task, state, k=0.5, alpha=0.5, beta=1.0):
    p = max(task.estimated_runtime, 1e-6)
    c = max(task.resource_need, 1e-6)
    slack = max(0.0, task.due - p - state.now)
    base = task.weight / p * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    if c <= state.free:
        fit_factor = 1.0 + alpha * (state.free - c) / max(state.capacity, 1e-6)
    else:
        fit_factor = (max(state.free, 1e-6) / c) ** beta
    return base * fit_factor  # tuned (k=0.229,alpha=0.478,beta=0.69)

