def priority(task, state, k=0.5, b=1.0, m_prem=1.0, m_std=1.0, m_align=1.0, m_var=1.0, m_sv=1.0):
    p = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = max(0.0, task.due - state.now - p)
    base = task.weight / p * math.exp(-slack / max(max(k, 1e-6) * mean_est, 1e-6))
    wait = max(0.0, state.now - task.release)
    window = max(task.due - task.release, 1e-6)
    age = 1.0 + b * wait / window
    if task.tenant == 'premium':
        base *= m_prem
    else:
        base *= m_std
    if task.task_type == 'alignment':
        base *= m_align
    elif task.task_type == 'variant_calling':
        base *= m_var
    else:
        base *= m_sv
    return base * age
